import { test, expect } from '@playwright/test';

test.describe('Modal Focus Trap', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body>' +
      '<button id="openModal">Open Modal</button>' +
      '<div id="modal" style="display:none; position:fixed; top:50%; left:50%; transform:translate(-50%,-50%); background:white; border:1px solid black; padding:20px; z-index:1000;">' +
      '<h2>Modal Dialog</h2>' +
      '<input type="text" id="firstInput" placeholder="First input" />' +
      '<input type="text" id="secondInput" placeholder="Second input" />' +
      '<button id="closeModal">Close</button>' +
      '</div>' +
      '<div id="backdrop" style="display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.5); z-index:999;"></div>' +
      '<button id="outsideButton">Outside Button</button>' +
      '<script>' +
      'const modal = document.getElementById("modal");' +
      'const backdrop = document.getElementById("backdrop");' +
      'const openBtn = document.getElementById("openModal");' +
      'const closeBtn = document.getElementById("closeModal");' +
      'const firstInput = document.getElementById("firstInput");' +
      'const secondInput = document.getElementById("secondInput");' +
      'const outsideBtn = document.getElementById("outsideButton");' +
      'const focusableElements = [firstInput, secondInput, closeBtn];' +
      'let isModalOpen = false;' +
      'openBtn.addEventListener("click", () => {' +
      '  modal.style.display = "block";' +
      '  backdrop.style.display = "block";' +
      '  isModalOpen = true;' +
      '  firstInput.focus();' +
      '  modal.addEventListener("keydown", trapFocus);' +
      '});' +
      'closeBtn.addEventListener("click", () => {' +
      '  modal.style.display = "none";' +
      '  backdrop.style.display = "none";' +
      '  isModalOpen = false;' +
      '  modal.removeEventListener("keydown", trapFocus);' +
      '  openBtn.focus();' +
      '});' +
      'backdrop.addEventListener("click", () => {' +
      '  modal.style.display = "none";' +
      '  backdrop.style.display = "none";' +
      '  isModalOpen = false;' +
      '  modal.removeEventListener("keydown", trapFocus);' +
      '});' +
      'function trapFocus(e) {' +
      '  if (e.key !== "Tab") return;' +
      '  const firstElement = focusableElements[0];' +
      '  const lastElement = focusableElements[focusableElements.length - 1];' +
      '  const activeElement = document.activeElement;' +
      '  if (e.shiftKey) {' +
      '    if (activeElement === firstElement) {' +
      '      e.preventDefault();' +
      '      lastElement.focus();' +
      '    }' +
      '  } else {' +
      '    if (activeElement === lastElement) {' +
      '      e.preventDefault();' +
      '      firstElement.focus();' +
      '    }' +
      '  }' +
      '}' +
      '</script>' +
      '</body></html>');
  });

  test('should trap focus within modal when modal is open', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const firstInput = page.locator('#firstInput');
    const secondInput = page.locator('#secondInput');
    const closeButton = page.getByRole('button', { name: 'Close' });

    // Open the modal
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Verify focus is on first input
    await expect(firstInput).toBeFocused();

    // Tab to second input
    await firstInput.press('Tab');
    await expect(secondInput).toBeFocused();

    // Tab to close button
    await secondInput.press('Tab');
    await expect(closeButton).toBeFocused();

    // Tab should wrap back to first input (focus trap)
    await closeButton.press('Tab');
    await expect(firstInput).toBeFocused();
  });

  test('should trap focus when shift+tab is pressed in modal', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const firstInput = page.locator('#firstInput');
    const closeButton = page.getByRole('button', { name: 'Close' });

    // Open the modal
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Focus is on first input
    await expect(firstInput).toBeFocused();

    // Shift+Tab should wrap to close button (last focusable element)
    await firstInput.press('Shift+Tab');
    await expect(closeButton).toBeFocused();

    // Shift+Tab again should go to second input
    await closeButton.press('Shift+Tab');
    const secondInput = page.locator('#secondInput');
    await expect(secondInput).toBeFocused();

    // Shift+Tab again should wrap to close button
    await secondInput.press('Shift+Tab');
    await expect(firstInput).toBeFocused();
  });

  test('should release focus trap when modal is closed', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const closeButton = page.getByRole('button', { name: 'Close' });
    const outsideButton = page.getByRole('button', { name: 'Outside Button' });

    // Open the modal
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Close the modal
    await closeButton.click();

    // Verify modal is hidden
    await expect(modal).toBeHidden();

    // Focus should be on open button
    await expect(openButton).toBeFocused();

    // Should be able to focus outside button (focus trap is released)
    await outsideButton.focus();
    await expect(outsideButton).toBeFocused();
  });

  test('should prevent focus from escaping to outside elements while modal is open', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const outsideButton = page.getByRole('button', { name: 'Outside Button' });
    const firstInput = page.locator('#firstInput');

    // Open the modal
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Try to focus outside button
    await outsideButton.focus();

    // Focus should still be within modal (on first input)
    await expect(firstInput).toBeFocused();
  });
});
